    "call-failure": "Call completion",
    "application-error": "Work IQ result",
    "result-status": "Reported result status",
    "conflicting-result-status": "Conflicting reported statuses",
    "recorded-error": "Recorded error code",
    "returned-api-error": "Returned API result",
    "conflicting-returned-status": "Conflicting returned status",
    "conflicting-diagnostic-status": "Conflicting diagnostic status",
    "recorded-request-timeout": "Retained timeout signal",
