    ...snapshot.reportPopulation.focus.outcome !== "errors" ? [{ kind: "operation", title: "Recorded operations" }] : [],
    ...groups.some((group) => group.kind === "errors") ? [{ kind: "errors", title: "Recorded error patterns" }] : []
